import { splitMessage } from './core.mjs';

export function escapeHtml(text) {
  return text.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
}

// Native Telegram blockquotes, not simulated CSS/glass (unsupported in chat).
// Only our own wrappers become HTML; everything generated by the model is escaped.
export function formatReply(text) {
  const sections = [];
  const pattern = /\[OPINION\]([\s\S]*?)\[\/OPINION\]/g;
  let at = 0;
  for (const match of text.matchAll(pattern)) {
    if (match.index > at) sections.push({ text: text.slice(at, match.index), opinion: false });
    if (match[1].trim()) sections.push({ text: `💬 نظر امیر\n${match[1].trim()}`, opinion: true });
    at = match.index + match[0].length;
  }
  if (at < text.length) sections.push({ text: text.slice(at), opinion: false });
  // Incomplete model markers (e.g. token-limit truncation) must not leak to chat.
  const clean = sections.map(section => ({ ...section,
    text: section.text.replaceAll('[OPINION]', '').replaceAll('[/OPINION]', '').trim(),
  })).filter(section => section.text);
  const render = section => section.opinion
    ? `<blockquote>${escapeHtml(section.text)}</blockquote>` : escapeHtml(section.text);
  if (clean.reduce((size, section) => size + section.text.length + 2, 0) <= 3500) {
    return clean.length ? [{ text: clean.map(render).join('\n\n'), parse_mode: 'HTML' }] : [];
  }
  return clean.flatMap(section => splitMessage(section.text, 3500).map(text => ({
    text: render({ ...section, text }), parse_mode: 'HTML',
  })));
}
